n = int(input())
previous = []
sum = 0
for i in range(n):
	size = input()
	previous.append(size)
for i in range(n):
	size = input()
	len_size = len(size)
	min_len = len_size
	if size not in previous:
		for m in range(n):
			for j in range(len_size):
				if size[j] in previous[m]:
					len_size -= 1
					min_len = len_size
	sum += min_len
